STATUS = {}


class Abort(Exception):
    pass


def log(*a):
    print(f"[{time.time() - T0:7.1f}s]", *a, flush=True)


def status(stage, **kw):
    STATUS[stage] = dict(t=round(time.time() - T0, 1), **kw)
    json.dump(STATUS, open(OUT + "/stage_status.json", "w"), indent=1)


def snapshot():
    """Copy the small outputs to /kaggle/working/out (called during and after the run so a crash loses nothing)."""
    try:
        p = ROOT + "/TEST-LOG-CT2.md"
        if os.path.exists(p):
            shutil.copy2(p, OUT + "/TEST-LOG-CT2.md")
            json.dump({"text": open(p).read()}, open(OUT + "/test_log_ct2.json", "w"))
        for pat, sub in ((ROOT + "/results/ct_*", "results"), (ROOT + "/results/figs/*", "results/figs"),
                         (ROOT + "/runs/ct_final_*", "runs"), (ROOT + "/edge_out/*.c", "edge"), (ROOT + "/edge_out/params/*", "edge/params")):
            os.makedirs(f"{OUT}/{sub}", exist_ok=True)
            for f in glob.glob(pat):
                if os.path.isfile(f):
                    shutil.copy2(f, f"{OUT}/{sub}/")
    except Exception:
        log("snapshot failed:", traceback.format_exc())


def sh(cmd, name, env=None, cwd=None, check=True, on_line=None):
    log("$", " ".join(cmd))
    buf = []
    with open(f"{OUT}/stages/{name}.log", "a") as lf:
        p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, env=env or ENV, cwd=cwd, bufsize=1)
        for line in p.stdout:
            print(line, end="", flush=True)
            lf.write(line)
            buf.append(line)
            if on_line:
                on_line(line)
        rc = p.wait()
    if check and rc != 0:
        raise Abort(f"{name}: command failed with exit code {rc}")
    return rc, "".join(buf)


def sha256_file(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def stage_banner():
    info = dict(utc_start=time.strftime("%Y-%m-%d %H:%M:%S", time.gmtime(T0)), python=sys.version, platform=platform.platform(),
                cpu_count=os.cpu_count(), kernel=KERNEL)
    try:
        info["cpu_model"] = [l.split(":", 1)[1].strip() for l in open("/proc/cpuinfo") if l.lower().startswith("model name")][0]
        info["mem_total_kb"] = [int(l.split()[1]) for l in open("/proc/meminfo") if l.startswith("MemTotal")][0]
    except Exception:
        pass
    json.dump(info, open(OUT + "/env.json", "w"), indent=1)
    log("ENV", json.dumps(info))
    log("EXPECT", json.dumps({k: v for k, v in EXPECT.items() if k != "manifest"}))


def stage_payload():
    if os.path.exists(ROOT):
        shutil.rmtree(ROOT)
    os.makedirs(ROOT)
    raw = base64.b64decode(PAYLOAD_B64)
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as tf:
        try:
            tf.extractall(ROOT, filter="data")
        except TypeError:
            tf.extractall(ROOT)
    bad = []
    for rel, want in EXPECT["manifest"].items():
        p = os.path.join(ROOT, rel)
        got = sha256_file(p) if os.path.exists(p) else "MISSING"
        if got != want:
            bad.append((rel, want, got))
    for d in ("ct", "ct2"):
        names = {os.path.basename(k) for k in EXPECT["manifest"] if k.startswith(d + "/")}
        for p in glob.glob(ROOT + f"/{d}/*"):
            if os.path.basename(p) not in names:
                bad.append((p, "not in manifest", "extra file"))
    for rel, want in EXPECT["selection_kernel_sha256"].items():
        if sha256_file(os.path.join(ROOT, rel)) != want:
            bad.append((rel, want, "differs from the selection kernel's verified file"))
    for rel in EXPECT.get("executable", []):
        os.chmod(os.path.join(ROOT, rel), 0o755)
    os.makedirs(ROOT + "/runs", exist_ok=True)
    os.makedirs(ROOT + "/results", exist_ok=True)
    manifest_report = {rel: dict(sha256=sha256_file(os.path.join(ROOT, rel))) for rel in sorted(EXPECT["manifest"])}
    json.dump(manifest_report, open(OUT + "/manifest_verified.json", "w"), indent=1)
    for rel in sorted(EXPECT["manifest"]):
        log("SHA256", manifest_report[rel]["sha256"], rel)
    if bad:
        raise Abort("payload sha256 mismatch: " + json.dumps(bad))
    status("payload", ok=True, files=len(EXPECT["manifest"]))


def stage_venv():
    sh([sys.executable, "-m", "pip", "install", "-q", "uv"], "venv")
    uvbin = subprocess.check_output([sys.executable, "-c", "import uv; print(uv.find_uv_bin())"], text=True).strip()
    sh([uvbin, "venv", "--python", "3.12", VENV], "venv")
    sh([uvbin, "pip", "install", "--python", PY, *PINS], "venv")
    rc, txt = sh([uvbin, "pip", "freeze", "--python", PY], "venv")
    open(OUT + "/venv_freeze.txt", "w").write(txt)
    code = ("import sys, json, numpy, scipy, jax, jaxlib, matplotlib, nonlinear_benchmarks, importlib.metadata as m;"
            "print('VERSIONS', json.dumps(dict(python=sys.version.split()[0], numpy=numpy.__version__, scipy=scipy.__version__, jax=jax.__version__,"
            "jaxlib=jaxlib.__version__, matplotlib=matplotlib.__version__, nonlinear_benchmarks=m.version('nonlinear_benchmarks'))))")
    rc, txt = sh([PY, "-c", code], "venv")
    got = json.loads(txt.split("VERSIONS", 1)[1].strip().splitlines()[0])
    open(OUT + "/versions.json", "w").write(json.dumps(got, indent=1))
    wrong = {k: (v, got.get(k)) for k, v in EXPECT_VERSIONS.items() if got.get(k) != v}
    if wrong:
        raise Abort("package versions differ from round 1: " + json.dumps(wrong))
    status("venv", ok=True, versions=got)


def stage_git():
    g = ["git", "-c", "user.name=ct-kernel", "-c", "user.email=ct-kernel@localhost"]
    sh(["git", "init", "-q", "."], "git", cwd=ROOT)
    sh(g + ["add", ".gitignore", "ct", "ct2", FREEZE, PREREG], "git", cwd=ROOT)
    sh(g + ["commit", "-q", "-m", "frozen sources, byte-identical to control repo " + EXPECT["repo_head"][:7]], "git", cwd=ROOT)
    got = {}
    for k, ref in (("git_tree_ct", "HEAD:ct"), ("git_tree_ct2", "HEAD:ct2"), ("git_blob_freeze", "HEAD:" + FREEZE), ("git_blob_prereg", "HEAD:" + PREREG)):
        _, t = sh(["git", "rev-parse", ref], "git", cwd=ROOT)
        got[k] = t.strip()
        log("GIT", k, got[k], "expected", EXPECT[k])
    ok = all(got[k] == EXPECT[k] for k in got)
    status("git", ok=ok, **got)
    if not ok:
        raise Abort("git hashes of the frozen sources differ from the control repo")
    _, st = sh(["git", "status", "--porcelain", "--", "ct", "ct2", "results/FREEZE_*.json", PREREG], "git", cwd=ROOT)
    if st.strip():
        raise Abort("tree not clean after commit: " + st)


def stage_data():
    last = None
    for attempt in range(1, 4):
        shutil.rmtree(ROOT + "/data", ignore_errors=True)
        rc, txt = sh([PY, "tools/ct_data_check.py", EXPECT["data_zip_sha256"], EXPECT["data_mat_sha256"]], "data", cwd=ROOT, check=False)
        last = txt
        if rc == 0:
            line = [l for l in txt.splitlines() if l.startswith("DATA_CHECK ")][-1]
            status("data", ok=True, attempt=attempt, info=json.loads(line[len("DATA_CHECK "):]))
            return
        log(f"data attempt {attempt} failed (rc={rc}); retrying in 20 s")
        time.sleep(20)
    raise Abort("data check failed after 3 attempts (Drive blocked or checksum mismatch); NOT falling back to any other copy. Last output tail: " + (last or "")[-800:])


def stage_final():
    status("final", started=True)
    cmd = [PY, "ct2/final2.py", FREEZE, "--seeds", *SEEDS, "--workers", str(WORKERS)]
    rc, txt = sh(cmd, "final", cwd=ROOT, check=False, on_line=lambda l: snapshot() if l.startswith("seed ") else None)
    snapshot()
    status("final", ok=(rc == 0), rc=rc)
    if rc != 0:
        raise Abort("final2.py exited with %s (scored seeds, if any, are in TEST-LOG-CT2.md); it is NOT re-run" % rc)


def optional(stage, cmd, name):
    try:
        rc, _ = sh(cmd, name, cwd=ROOT, check=False)
        status(stage, ok=(rc == 0), rc=rc)
    except Exception:
        status(stage, ok=False, error=traceback.format_exc()[-600:])
        log(stage, "FAILED:", traceback.format_exc())
    snapshot()


def main():
    stage_banner()
    stage_payload()
    stage_venv()
    stage_git()
    stage_data()
    stage_final()
    optional("compare_ref", [PY, "ct/compare_ref.py", NAME], "compare_ref")
    optional("plots", [PY, "ct/plots.py", NAME], "plots")
    optional("aggregate", [PY, "tools/ct_aggregate.py", NAME], "aggregate")
    optional("edge", [PY, "tools/ct2_edge_run.py", FREEZE, "--seed", "0", "--out", "edge_out"], "edge")
    log("ALL STAGES DONE")


if __name__ == "__main__":
    rc = 0
    try:
        main()
    except Abort as e:
        log("ABORT:", e)
        status("abort", msg=str(e))
        rc = 2
    except Exception:
        log("CRASH:", traceback.format_exc())
        status("crash", tb=traceback.format_exc()[-800:])
        rc = 3
    snapshot()
    shutil.rmtree(ROOT + "/data", ignore_errors=True)
    log("elapsed", round(time.time() - T0), "s")
    sys.exit(rc)
